    ('instruction', 'A2', '/ɪnˈstrʌkʃən/', 'n', 'struct', [('prefix', 'in-', 'vào trong'), ('root', 'struct', 'xây dựng'), ('suffix', '-ion', 'hành động')], 'sự hướng dẫn, chỉ dẫn', 'detailed information telling how to do something', 'Xây dựng từng bước kiến thức vào bên trong đầu người khác — tức là giảng dạy/hướng dẫn.', [('follow instructions', 'làm theo hướng dẫn'), ('step-by-step instructions', 'chỉ dẫn từng bước'), ('clear instructions', 'hướng dẫn rõ ràng')], 'Read the instructions carefully before starting the test.', 'Hãy đọc kỹ hướng dẫn trước khi bắt đầu bài kiểm tra.'),
    ('construct', 'B1', '/kənˈstrʌkt/', 'v', 'struct', [('prefix', 'con-', 'cùng nhau'), ('root', 'struct', 'xây dựng')], 'xây dựng, kiến thiết', 'to build or form something complex', 'Gom nhiều vật liệu lại cùng nhau và dựng thành một công trình hay lập luận.', [('construct a building', 'xây dựng tòa nhà'), ('construct an argument', 'xây dựng lập luận'), ('under construction', 'đang thi công')], 'They plan to construct a new library in the city center.', 'Họ dự định xây dựng một thư viện mới ở trung tâm thành phố.'),
