    ('dictionary', 'A1', '/ˈdɪkʃənˌɛri/', 'n', 'dict', [('root', 'dict', 'lời nói, từ ngữ'), ('suffix', '-ary', 'nơi chứa/cuốn sách')], 'từ điển', 'a book or app listing words and meanings', 'Kho sách tập hợp các lời nói và cách định nghĩa từ ngữ.', [('look up in a dictionary', 'tra từ điển'), ('bilingual dictionary', 'từ điển song ngữ'), ('pocket dictionary', 'từ điển bỏ túi')], 'Use a dictionary to verify pronunciation whenever you doubt.', 'Hãy dùng từ điển để kiểm tra phát âm bất cứ khi nào bạn phân vân.'),
