    ('contradict', 'B2', '/ˌkɑːntrəˈdɪkt/', 'v', 'dict', [('prefix', 'contra-', 'chống lại, trái ngược'), ('root', 'dict', 'nói')], 'mâu thuẫn, phản bác lại', 'to say the opposite of another statement', 'Nói điều hoàn toàn ngược chiều lại với phát biểu trước đó.', [('contradict oneself', 'tự mâu thuẫn với mình'), ('directly contradict', 'trái ngược hoàn toàn'), ('internal contradiction', 'mâu thuẫn nội tại')], 'His actions directly contradict the promises he made.', 'Hành động của anh ấy mâu thuẫn trực tiếp với những lời hứa đã nói.'),
    ('verdict', 'B2', '/ˈvɜːrdɪkt/', 'n', 'dict', [('prefix', 'ver-', 'sự thật (verus)'), ('root', 'dict', 'lời tuyên bố')], 'phán quyết, lời kết luận', 'an official judgment in court or debate', 'Lời tuyên bố sự thật (ver- = truth + dict = say) của bồi thẩm đoàn hoặc người đánh giá.', [('reach a verdict', 'đưa ra phán quyết'), ('guilty verdict', 'phán quyết có tội'), ('final verdict', 'kết luận cuối cùng')], 'The jury took three hours to reach a unanimous verdict.', 'Bồi thẩm đoàn mất ba tiếng để đi đến phán quyết đồng thuận.'),
    ('dedicate', 'B2', '/ˈdɛdɪkeɪt/', 'v', 'dict', [('prefix', 'de-', 'hoàn toàn'), ('root', 'dic', 'tuyên bố dâng hiến'), ('suffix', '-ate', 'thực hiện')], 'cống hiến, dành trọn', 'to devote time or effort completely', 'Long trọng tuyên bố dành trọn tâm huyết cho một mục tiêu hay người nào đó.', [('dedicate time to', 'dành thời gian cho'), ('dedicated team', 'đội ngũ tận tâm'), ('deeply dedicated', 'cống hiến hết mình')], 'She dedicated ten years of her life to medical research.', 'Cô ấy đã cống hiến mười năm cuộc đời cho nghiên cứu y học.'),
    ('dictate', 'C1', '/ˈdɪkteɪt/', 'v', 'dict', [('root', 'dict', 'ra lệnh, đọc chép'), ('suffix', '-ate', 'thực hiện')], 'đọc chính tả; chi phối, áp đặt', 'to read aloud for transcription or control decisively', 'Nói dứt khoát từng chữ cho người khác chép hoặc đặt ra luật lệ bắt tuân theo.', [('dictate terms', 'áp đặt điều kiện'), ('dictated by budget', 'bị chi phối bởi ngân sách'), ('dictation practice', 'luyện nghe chép chính tả')], 'Market demand often dictates the direction of new products.', 'Nhu cầu thị trường thường chi phối định hướng của các sản phẩm mới.'),

