    ('distract', 'B1', '/dɪˈstrækt/', 'v', 'tract', [('prefix', 'dis-', 'tách rẽ các hướng'), ('root', 'tract', 'kéo')], 'làm xao nhãng, phân tâm', 'to pull attention away from what matters', 'Kéo tâm trí bạn rẽ sang hướng khác khỏi việc đang tập trung.', [('distract someone from', 'làm ai xao nhãng khỏi'), ('avoid distractions', 'tránh xao nhãng'), ('easily distracted', 'dễ bị phân tâm')], 'Constant notifications distract your brain from deep reading.', 'Thông báo liên tục kéo não bạn xao nhãng khỏi việc đọc sâu.'),
