    ('subtract', 'A2', '/səbˈtrækt/', 'v', 'tract', [('prefix', 'sub-', 'từ bên dưới'), ('root', 'tract', 'kéo đi')], 'trừ đi, khấu trừ', 'to take away a number from another', 'Rút bớt một phần từ bên dưới tổng số ban đầu.', [('subtract expenses', 'trừ chi phí'), ('add and subtract', 'cộng và trừ'), ('subtraction error', 'lỗi phép trừ')], 'If you subtract taxes from gross pay, you get net income.', 'Nếu trừ thuế khỏi lương gộp, bạn sẽ ra thu nhập thực nhận.'),
