    ('adventure', 'B1', '/ədˈvɛntʃər/', 'n', 'ven', [('prefix', 'ad-', 'hướng tới'), ('root', 'vent', 'điều sắp đến'), ('suffix', '-ure', 'trải nghiệm')], 'cuộc phiêu lưu, mạo hiểm', 'an exciting and risky experience', 'Bước tới đón nhận những điều mới mẻ sắp ập đến.', [('great adventure', 'cuộc phiêu lưu lớn'), ('sense of adventure', 'tinh thần phiêu lưu'), ('adventurous spirit', 'tâm hồn ưa khám phá')], 'Exploring etymology turns vocabulary study into a mental adventure.', 'Khám phá nguồn gốc từ biến việc học từ vựng thành chuyến phiêu lưu trí tuệ.'),
    ('convenient', 'B1', '/kənˈviːniənt/', 'adj', 'ven', [('prefix', 'con-', 'cùng nhau'), ('root', 'ven', 'đến, khớp'), ('suffix', '-ient', 'tính chất')], 'thuận tiện, tiện lợi', 'fitting well with needs and schedule', 'Mọi yếu tố cùng kéo đến khớp vừa vặn với lịch trình và nhu cầu của bạn.', [('convenient location', 'vị trí thuận lợi'), ('convenience store', 'cửa hàng tiện lợi'), ('at your convenience', 'lúc nào bạn tiện')], 'Local storage makes progress sync instant and convenient.', 'Lưu cục bộ giúp đồng bộ tiến độ tức thì và vô cùng tiện lợi.'),
    ('convention', 'B2', '/kənˈvɛnʃən/', 'n', 'ven', [('prefix', 'con-', 'cùng nhau'), ('root', 'vent', 'đến họp'), ('suffix', '-ion', 'hành động/tổ chức')], 'hội nghị, quy ước, tập tục', 'a large meeting or widely accepted custom', 'Nhiều người cùng đi đến một nơi (hội nghị) hoặc cùng thống nhất quy ước chung.', [('social convention', 'quy ước xã hội'), ('annual convention', 'hội nghị thường niên'), ('conventional wisdom', 'quan niệm thông thường')], 'Conventional flashcards lack root dissection and active spelling.', 'Thẻ ghi nhớ thông thường thiếu phần giải phẫu gốc từ và gõ chính tả chủ động.'),
    ('intervene', 'C1', '/ˌɪntərˈviːn/', 'v', 'ven', [('prefix', 'inter-', 'vào giữa'), ('root', 'ven', 'bước vào')], 'can thiệp, xen vào', 'to step in to change an outcome', 'Bước chân xen vào giữa hai bên để dàn xếp hoặc ngăn sự việc leo thang.', [('intervene early', 'can thiệp sớm'), ('government intervention', 'sự can thiệp của nhà nước'), ('intervene in a dispute', 'can thiệp tranh chấp')], 'Teachers intervene only after students attempt solving problems alone.', 'Giáo viên chỉ can thiệp sau khi học sinh đã tự mình thử giải quyết vấn đề.'),

