    ('transfer', 'B1', '/ˈtrænsfɜːr/', 'v/n', 'fer', [('prefix', 'trans-', 'sang bên kia'), ('root', 'fer', 'chuyển, mang')], 'chuyển đổi, chuyển khoản, di chuyển', 'to move from one place or person to another', 'Mang từ vị trí này băng qua sang đặt tại vị trí khác.', [('bank transfer', 'chuyển khoản ngân hàng'), ('transfer knowledge', 'truyền đạt kiến thức'), ('data transfer', 'truyền dữ liệu')], 'Transferring skills across Japanese and English strengthens memory.', 'Chuyển giao kỹ năng giữa Tiếng Nhật và Tiếng Anh giúp củng cố trí nhớ.'),
    ('refer', 'B1', '/rɪˈfɜːr/', 'v', 'fer', [('prefix', 're-', 'trở lại'), ('root', 'fer', 'mang, dẫn')], 'tham khảo, đề cập đến', 'to mention or look at a source', 'Đưa sự chú ý quay trở lại nguồn tài liệu gốc để kiểm chứng.', [('refer to notes', 'tham khảo ghi chú'), ('reference book', 'sách tham khảo'), ('in reference to', 'liên quan tới')], 'You can refer to the root family list on the right panel.', 'Bạn có thể tham khảo danh sách họ từ cùng gốc ở cột bên phải.'),
    ('suffer', 'B1', '/ˈsʌfər/', 'v', 'fer', [('prefix', 'suf(sub)-', 'ở bên dưới'), ('root', 'fer', 'chịu đựng, gánh')], 'chịu đựng, mắc phải (đau khổ)', 'to experience pain or hardship', 'Phải cúi xuống gánh chịu sức nặng đè lên từ phía trên.', [('suffer from stress', 'chịu căng thẳng'), ('suffer losses', 'gánh chịu tổn thất'), ('sleep deprivation suffering', 'khổ sở vì thiếu ngủ')], 'Attention spans suffer when we consume thirty-second clips nonstop.', 'Khả năng tập trung bị tổn hại khi ta xem video 30 giây không ngừng nghỉ.'),
