    ('project', 'B1', '/ˈprɑːdʒɛkt/', 'n/v', 'ject', [('prefix', 'pro-', 'về phía trước'), ('root', 'ject', 'phóng ra')], 'dự án; phóng chiếu, dự báo', 'planned work; to throw an image or forecast forward', 'Ném bản kế hoạch hoặc hình ảnh vươn về phía tương lai phía trước.', [('side project', 'dự án cá nhân'), ('project onto a screen', 'chiếu lên màn hình'), ('projected growth', 'tăng trưởng dự kiến')], 'Building a bilingual study app is a rewarding long-term project.', 'Xây dựng ứng dụng học song ngữ là một dự án dài hạn rất đáng giá.'),
    ('reject', 'B1', '/rɪˈdʒɛkt/', 'v/n', 'ject', [('prefix', 're-', 'đẩy ngược lại'), ('root', 'ject', 'ném')], 'từ chối, bác bỏ, loại bỏ', 'to refuse to accept or agree', 'Ném trả ngược lại vật hoặc lời đề nghị vì không đạt yêu cầu.', [('reject an offer', 'từ chối lời mời'), ('reject a theory', 'bác bỏ học thuyết'), ('fear of rejection', 'nỗi sợ bị từ chối')], 'Your brain will reject new words unless they carry meaning.', 'Não bạn sẽ đào thải từ mới nếu chúng không gắn với ý nghĩa cụ thể.'),
    ('inject', 'B2', '/ɪnˈdʒɛkt/', 'v', 'ject', [('prefix', 'in-', 'vào bên trong'), ('root', 'ject', 'phóng, đẩy')], 'tiêm vào, bơm vào, thổi luồng mới', 'to put liquid or energy inside something', 'Bơm đẩy thẳng chất lỏng hoặc năng lượng mới vào bên trong.', [('inject capital', 'bơm vốn'), ('inject fresh energy', 'tiếp sinh khí mới'), ('flu injection', 'tiêm phòng cúm')], 'Examples inject real-life context into dry dictionary entries.', 'Các câu ví dụ thổi ngữ cảnh đời thực vào mục từ điển khô khan.'),
    ('trajectory', 'C1', '/trəˈdʒɛktəri/', 'n', 'ject', [('prefix', 'tra(trans)-', 'băng qua'), ('root', 'ject', 'ném đi'), ('suffix', '-ory', 'đường đi')], 'quỹ đạo, lộ trình phát triển', 'curved path of an object or career', 'Đường bay vạch ra khi một vật bị phóng đi xuyên qua không gian.', [('upward trajectory', 'đà đi lên'), ('career trajectory', 'lộ trình sự nghiệp'), ('flight trajectory', 'quỹ đạo bay')], 'Daily review changes your memory curve into an upward trajectory.', 'Ôn tập mỗi ngày xoay chuyển đường cong trí nhớ theo quỹ đạo đi lên.'),
    ('conjecture', 'C1', '/kənˈdʒɛktʃər/', 'n/v', 'ject', [('prefix', 'con-', 'gộp chung'), ('root', 'ject', 'phóng đoán'), ('suffix', '-ure', 'kết quả')], 'sự phỏng đoán chưa có chứng cứ', 'an opinion formed on incomplete info', 'Tung ra một giả thuyết gộp từ phỏng đoán khi chưa đủ dữ liệu chứng minh.', [('pure conjecture', 'suy đoán thuần túy'), ('open to conjecture', 'còn để ngỏ suy đoán'), ('scientific conjecture', 'giả thuyết khoa học')], 'Verify dictionary roots cleanly instead of relying on guesswork or conjecture.', 'Hãy kiểm chứng gốc từ rõ ràng thay vì chỉ dựa vào phỏng đoán.'),

