    ('accept', 'A1', '/əkˈsɛpt/', 'v', 'cap', [('prefix', 'ac(ad)-', 'hướng về mình'), ('root', 'cept', 'nhận lấy')], 'chấp nhận, đồng ý nhận', 'to agree to take or receive', 'Đưa tay kéo hướng về phía mình và cầm lấy vật được trao.', [('accept an invitation', 'chấp nhận lời mời'), ('widely accepted', 'được chấp nhận rộng rãi'), ('accept mistakes', 'chấp nhận sai sót')], 'Accept early mistakes as normal feedback for deeper recall.', 'Hãy chấp nhận những lỗi sai ban đầu như tín hiệu bình thường để nhớ sâu hơn.'),
