    ('credentials', 'C1', '/krəˈdɛnʃəlz/', 'n', 'cred', [('root', 'cred', 'sự tín nhiệm'), ('suffix', '-ial', 'chứng thực')], 'giấy tờ chứng nhận năng lực, bằng cấp', 'documents proving qualifications or identity', 'Giấy chứng nhận chứng minh bạn xứng đáng được trao niềm tin chuyên môn.', [('academic credentials', 'bằng cấp học thuật'), ('verify credentials', 'xác minh chứng chỉ'), ('login credentials', 'thông tin đăng nhập')], 'Strong practical skills matter just as much as formal credentials.', 'Kỹ năng thực chiến vững vàng quan trọng ngang với bằng cấp hình thức.'),
