    ('benefit', 'B1', '/ˈbɛnɪfɪt/', 'n/v', 'fac', [('prefix', 'bene-', 'tốt đẹp'), ('root', 'fit(fic)', 'làm')], 'lợi ích; mang lại lợi ích', 'an advantage or profit gained from something', 'Làm ra (facere) những điều tốt đẹp (bene) mang lại giá trị cho con người.', [('health benefits', 'lợi ích sức khỏe'), ('benefit from', 'hưởng lợi từ'), ('mutual benefit', 'lợi ích chung')], 'Students benefit enormously from testing themselves before checking answers.', 'Học sinh hưởng lợi rất lớn khi tự kiểm tra trước khi xem đáp án.'),
    ('artifact', 'C1', '/ˈɑːrtəˌfækt/', 'n', 'fac', [('prefix', 'arti-', 'kỹ nghệ, nghệ thuật'), ('root', 'fact', 'vật được tạo ra')], 'cổ vật, tạo tác nhân tạo', 'an object made by humans of historical value', 'Vật thể được làm ra (fact) bằng kỹ năng nghệ thuật (art) của bàn tay con người.', [('ancient artifact', 'cổ vật xưa'), ('cultural artifact', 'hiện vật văn hóa'), ('software artifact', 'sản phẩm phần mềm')], 'Each ceramic artifact reflects the daily craft of its era.', 'Mỗi hiện vật gốm phản ánh trình độ thủ công của thời đại đó.'),

